import math

N = 67848
sqrt_N = math.isqrt(N)
print(f"Factorization of {N}:")

# Prime factorization
factors = {}
d = 2
temp = N
while d * d <= temp:
    while temp % d == 0:
        factors[d] = factors.get(d, 0) + 1
        temp //= d
    d += 1
if temp > 1:
    factors[temp] = factors.get(temp, 0) + 1
print(f"Prime factorization: {factors}")

# Search for factors X in the required range [250, 260]
print("\nSearching for factors X in [250, 260]:")
possible_factors_X = []
# Iterate through all factors of N up to sqrt(N)
all_factors = []
for i in range(1, sqrt_N + 1):
    if N % i == 0:
        all_factors.append(i)

all_factors.sort()

for X in all_factors:
    if X >= 250 and X <= sqrt_N:
        Y = N // X
        if Y >= 250:
            # Check if X and Y lead to integer solutions for a3, a4
            # X = 257*a3 - 264  => a3 = (X + 264) / 257
            # Y = 257*a4 - 264  => a4 = (Y + 264) / 257
            a3_num = X + 264
            a4_num = Y + 264

            if a3_num % 257 == 0 and a4_num % 257 == 0:
                a3 = a3_num // 257
                a4 = a4_num // 257
                possible_factors_X.append({
                    "X": X, "Y": Y, "a3": a3, "a4": a4
                })

print(f"Factors satisfying X >= 250 and Y >= 250: {[f for f in all_factors if f >= 250 and N//f >= 250]}")
if possible_factors_X:
    print("\nFound integer solutions:")
    for sol in possible_factors_X:
        print(f"X={sol['X']}, Y={sol['Y']}, a3={sol['a3']}, a4={sol['a4']}")
else:
    print("\nNo factors satisfy the constraints AND result in integer a3, a4.")

